SELECT \"nct\", \"author\", \"year\", \"pubmed_id\" FROM public.\"clinical_trials\" WHERE \"cancer_type\" ILIKE '%Non-Small Cell Lung%' AND \"included_in_ma\" = 't' AND (\"class_of_ici\" = 'PD1' OR \"class_of_ici\" = 'CTLA-4')", "answer": "Non-Small Cell Lung studies included in the meta-analysis that used PD1 or CTLA-4 agents are listed.", "assumptions": "Assumed that 'PD1' and 'CTLA-4' are correctly mapped to the 'class_of_ici' column and that 'Non-Small Cell Lung' is a substring within the 'cancer_type' column."}
